g=[[0]*19 for _ in range(19)]
# colored centers and 3 arms
centers={(3,6):8,(4,13):4,(12,14):1,(14,3):2,(10,8):0}
for (r,c),v in centers.items():
    g[r][c]=v
    for dr,dc in [(-1,0),(1,0),(0,-1),(0,1)]: g[r+dr][c+dc]=3
# rays: paint all rows and columns of nonzero centers, preserving 3 markers; vertical rays first, then horizontal only where still blank
out=[row[:] for row in g]
for (r,c),v in centers.items():
    if v:
        for rr in range(19):
            if out[rr][c]!=3: out[rr][c]=v
for (r,c),v in centers.items():
    if v:
        for cc in range(19):
            if out[r][cc] not in (3,) and not (cc in [c2 for (r2,c2),v2 in centers.items() if v2 and r2==rr] if False else False):
                # don't overwrite vertical ray colors; easiest identify occupied vertical colors from original set
                if out[r][cc]==0: out[r][cc]=v
# print
print('\n'.join(' '.join(map(str,row)) for row in out))

# regenerate source arrangement
orig=[[0]*19 for _ in range(19)]
centers={(3,6):8,(4,13):4,(12,14):1,(14,3):2,(10,8):0}
for (r,c),v in centers.items():
    orig[r][c]=v
    for dr,dc in [(-1,0),(1,0),(0,-1),(0,1)]: orig[r+dr][c+dc]=3
src=[(r,c,v) for (r,c),v in centers.items() if v]
H=W=19
out=[row[:] for row in orig]
def extend(r,c,v,dr,dc, vertical=False):
    rr,cc=r+dr,c+dc
    first=True
    while 0<=rr<H and 0<=cc<W:
        if orig[rr][cc]==3:
            if first: # own adjacent marker along ray
                first=False; rr+=dr; cc+=dc; continue
            break
        first=False
        if orig[rr][cc] not in (1,2,4,8) and out[rr][cc]==0:
            out[rr][cc]=v
        rr+=dr; cc+=dc
# vertical first
for r,c,v in src:
    for dr in (-1,1): extend(r,c,v,dr,0,True)
# horizontal second; only color empty to retain vertical lines
for r,c,v in src:
    for dc in (-1,1): extend(r,c,v,0,dc)
print('\n'.join(' '.join(map(str,row)) for row in out))
